package com.labmaker.app;
import org.junit.*;import static org.junit.Assert.*;import okhttp3.*;import okhttp3.mockwebserver.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.concurrent.TimeUnit;
public class MobileAppDownloadTest{
 private MockWebServer server;private MobileAppDownload download;private File directory;private final String id="aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
 @Before public void start()throws Exception{server=new MockWebServer();server.start();download=new MobileAppDownload(new OkHttpClient.Builder().callTimeout(2,TimeUnit.SECONDS).build(),server.url("/"));directory=Files.createTempDirectory("mobile-apk-test-").toFile();}
 @After public void stop()throws Exception{server.shutdown();File[] files=directory.listFiles();if(files!=null)for(File f:files)f.delete();directory.delete();}
 private String url(){return server.url("/mobile-app/lab-maker-app-1.0.1.apk").toString();}
 private String hash(String value)throws Exception{return MobileAppDownload.hex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}
 @Test public void exactAnonymousStreamIsPublishedOnlyAfterHash()throws Exception{String value="apk test bytes";server.enqueue(new MockResponse().setBody(value).addHeader("Set-Cookie","account=ignored"));File file=download.download(url(),"1.0.1",value.length(),hash(value),directory,id,new MobileDataDownload.Work(),(a,b)->{});assertEquals(value,new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));assertFalse(new File(directory,id+".part").exists());RecordedRequest request=server.takeRequest();assertNull(request.getHeader("Cookie"));assertNull(request.getHeader("Authorization"));assertEquals("GET",request.getMethod());}
 @Test public void sourceBoundsRedirectAndHashFailureLeaveNoCandidate()throws Exception{for(String bad:new String[]{url()+"?token=x",url()+"#x",url().replace("1.0.1","1.0.2"),"https://example.com/mobile-app/lab-maker-app-1.0.1.apk"})assertThrows(Exception.class,()->download.download(bad,"1.0.1",2,hash("{}"),directory,id,new MobileDataDownload.Work(),(a,b)->{}));assertEquals(0,server.getRequestCount());server.enqueue(new MockResponse().setResponseCode(302).addHeader("Location",server.url("/other")));assertThrows(Exception.class,()->download.download(url(),"1.0.1",2,hash("{}"),directory,id,new MobileDataDownload.Work(),(a,b)->{}));server.enqueue(new MockResponse().setBody("xx"));assertThrows(Exception.class,()->download.download(url(),"1.0.1",2,hash("{}"),directory,id,new MobileDataDownload.Work(),(a,b)->{}));assertEquals(0,directory.list().length);}
 @Test public void partialOversizeAndCancellationNeverPublish()throws Exception{server.enqueue(new MockResponse().setChunkedBody("12345",1));assertThrows(Exception.class,()->download.download(url(),"1.0.1",3,hash("123"),directory,id,new MobileDataDownload.Work(),(a,b)->{}));assertEquals(0,directory.list().length);MobileDataDownload.Work work=new MobileDataDownload.Work();work.cancel();assertThrows(Exception.class,()->download.download(url(),"1.0.1",3,hash("123"),directory,id,work,(a,b)->{}));assertThrows(Exception.class,()->download.download(url(),"1.0.1",MobileAppDownload.MAX_APK+1,hash("123"),directory,id,new MobileDataDownload.Work(),(a,b)->{}));assertEquals(0,directory.list().length);}
 @Test public void packagePolicyRequiresExactInstalledIdentityAndHigherVersions()throws Exception{
  String certificate="b".repeat(64);Set<String> cert=Set.of(certificate);MobileAppPolicy.Info installed=new MobileAppPolicy.Info("com.labmaker.app","1.0.0",10,26,cert),next=new MobileAppPolicy.Info("com.labmaker.app","1.0.1",11,26,cert);MobileAppPolicy.validate(installed,next,"1.0.1",11,26,certificate,26);
  for(MobileAppPolicy.Info bad:new MobileAppPolicy.Info[]{new MobileAppPolicy.Info("evil.app","1.0.1",11,26,cert),new MobileAppPolicy.Info("com.labmaker.app","1.0.1",10,26,cert),new MobileAppPolicy.Info("com.labmaker.app","1.0.1",11,26,Set.of("c".repeat(64)))})assertThrows(Exception.class,()->MobileAppPolicy.validate(installed,bad,"1.0.1",11,26,certificate,26));
  assertThrows(Exception.class,()->MobileAppPolicy.validate(installed,next,"1.0.1",11,26,certificate,25));assertThrows(Exception.class,()->MobileAppPolicy.validate(installed,next,"1.0.2",11,26,certificate,26));
 }
 @Test public void applicationManifestUsesItsOwnFixedPath()throws Exception{server.enqueue(new MockResponse().setResponseCode(404));MobileDataDownload metadata=new MobileDataDownload(new OkHttpClient(),server.url("/"));assertFalse(metadata.appManifest(new MobileDataDownload.Work(),(a,b)->{}).getBoolean("found"));assertEquals("/mobile-app-manifest.json",server.takeRequest().getPath());}
 @Test public void api24PackageCanUpdateAnApi24Device()throws Exception{String c="b".repeat(64);MobileAppPolicy.validate(new MobileAppPolicy.Info("com.labmaker.app","1.0.0",10,24,Set.of(c)),new MobileAppPolicy.Info("com.labmaker.app","1.0.1",11,24,Set.of(c)),"1.0.1",11,24,c,24);}
}
